     // parsed (§1.3 D16, D17).
     var viewNames = map[string]ViewType{ ... "netdiag": ViewNetdiag, "net": ViewNetdiag, }

     var actionNames = map[string]CommandType{
     	"context": CommandContext, "theme": CommandTheme, "quit": CommandQuit,
