1	package credentials
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9	)
10	
11	// NewFileStorageForContext creates a FileStorage at ~/.devdesk/credentials-<context>.json.
12	// Used as a reliable fallback when the system credential helper (e.g. GCM on Windows) fails.
13	func NewFileStorageForContext(contextName string) *FileStorage {
14		if contextName == "" {
15			contextName = "default"
16		}
17		homeDir, _ := os.UserHomeDir()
18		path := filepath.Join(homeDir, ".devdesk", "credentials-"+contextName+".json")
19		return NewFileStorage(path)
20	}
21	
22	// ChainStorage tries multiple Storage implementations in order.
23	// Save writes to all storages (best effort). Load returns the first success. Delete removes from all.
24	type ChainStorage struct {
25		storages []Storage
26	}
27	
28	// NewChainStorage creates a ChainStorage that tries each storage in the given order.
29	func NewChainStorage(storages ...Storage) *ChainStorage {
30		return &ChainStorage{storages: storages}
31	}
32	
33	// Save saves to all storages, returning an error only if all fail.
34	func (c *ChainStorage) Save(url, token string) error {
35		var lastErr error
36		saved := false
37		for _, s := range c.storages {
38			if err := s.Save(url, token); err != nil {
39				lastErr = err
40			} else {
41				saved = true
42			}
43		}
44		if !saved {
45			return lastErr
46		}
47		return nil
48	}
49	
50	// Load tries each storage in order and returns the first token found.
51	func (c *ChainStorage) Load(url string) (string, error) {
52		for _, s := range c.storages {
53			token, err := s.Load(url)
54			if err == nil && token != "" {
55				return token, nil
56			}
57		}
58		return "", fmt.Errorf("no credentials found for %s", url)
59	}
60	
61	// Delete removes credentials from all storages (best effort).
62	func (c *ChainStorage) Delete(url string) error {
63		for _, s := range c.storages {
64			_ = s.Delete(url)
65		}
66		return nil
67	}
68	
69	// Storage interface pour stocker/récupérer les credentials
70	type Storage interface {
71		Save(url, token string) error
72		Load(url string) (token string, err error)
73		Delete(url string) error
74	}
75	
76	// FileStorage stocke les credentials dans un fichier JSON
77	type FileStorage struct {
78		filePath string
79	}
80	
81	// NewFileStorage crée un nouveau FileStorage
82	func NewFileStorage(filePath string) *FileStorage {
83		return &FileStorage{filePath: filePath}
84	}
85	
86	// Save sauvegarde un token
87	func (f *FileStorage) Save(url, token string) error {
88		// Charger les credentials existants
89		creds, err := f.loadAll()
90		if err != nil && !errors.Is(err, os.ErrNotExist) {
91			return err
92		}
93		if creds == nil {
94			creds = make(map[string]string)
95		}
96	
97		// Ajouter/mettre à jour le token
98		creds[url] = token
99	
100		// Sauvegarder
101		return f.saveAll(creds)
102	}
103	
104	// Load charge un token
105	func (f *FileStorage) Load(url string) (string, error) {
106		creds, err := f.loadAll()
107		if err != nil {
108			return "", err
109		}
110	
111		token, ok := creds[url]
112		if !ok {
113			return "", fmt.Errorf("no credentials found for %s", url)
114		}
115	
116		return token, nil
117	}
118	
119	// Delete supprime un token
120	func (f *FileStorage) Delete(url string) error {
121		creds, err := f.loadAll()
122		if err != nil {
123			return err
124		}
125	
126		delete(creds, url)
127	
128		return f.saveAll(creds)
129	}
130	
131	// loadAll charge tous les credentials
132	func (f *FileStorage) loadAll() (map[string]string, error) {
133		data, err := os.ReadFile(f.filePath)
134		if err != nil {
135			return nil, err
136		}
137	
138		var creds map[string]string
139		if err := json.Unmarshal(data, &creds); err != nil {
140			return nil, err
141		}
142	
143		return creds, nil
144	}
145	
146	// saveAll sauvegarde tous les credentials
147	func (f *FileStorage) saveAll(creds map[string]string) error {
148		// Créer le répertoire parent si nécessaire
149		dir := filepath.Dir(f.filePath)
150		if err := os.MkdirAll(dir, 0700); err != nil {
151			return err
152		}
153	
154		data, err := json.MarshalIndent(creds, "", "  ")
155		if err != nil {
156			return err
157		}
158	
159		// Écrire avec des permissions restrictives
160		return os.WriteFile(f.filePath, data, 0600)
161	}
162	
163	// MemoryStorage stocke les credentials en mémoire (session uniquement)
164	type MemoryStorage struct {
165		creds map[string]string
166	}
167	
168	// NewMemoryStorage crée un nouveau MemoryStorage
169	func NewMemoryStorage() *MemoryStorage {
170		return &MemoryStorage{
171			creds: make(map[string]string),
172		}
173	}
174	
175	// Save sauvegarde un token en mémoire
176	func (m *MemoryStorage) Save(url, token string) error {
177		m.creds[url] = token
178		return nil
179	}
180	
181	// Load charge un token depuis la mémoire
182	func (m *MemoryStorage) Load(url string) (string, error) {
183		token, ok := m.creds[url]
184		if !ok {
185			return "", fmt.Errorf("no credentials found for %s", url)
186		}
187		return token, nil
188	}
189	
190	// Delete supprime un token de la mémoire
191	func (m *MemoryStorage) Delete(url string) error {
192		delete(m.creds, url)
193		return nil
194	}
