// New crée une nouvelle App, dimensionnée sur le terminal courant.
func New(cfg *config.Config) *App {
	width, height, err := term.GetSize(os.Stdout.Fd())
	if err != nil {
		panic(err)
	}
	return newWithSize(cfg, width, height)
}

// newWithSize builds the router at a given size. New() reads that size from the
// terminal; splitting it out keeps the constructor itself free of I/O.
func newWithSize(cfg *config.Config, width, height int) *App {
	currentContext, _ := config.GetCurrentContext()
	sharedState := &shared.State{}

	app := &App{
		config:           cfg,
		currentContext:   currentContext,
		viewport:         newViewport(width, height),
		currentView:      defaultView(cfg),
		views:            make(map[command.ViewType]tea.Model),
		sharedState:      sharedState,
		commandInput:     newCommandInput(),
		completionEngine: command.NewCompletionEngine(),
		width:            width,
		height:           height,
	}

	// Les autres vues sont créées à la demande (lazy loading).
	app.createView(command.ViewDashboard)
	app.createView(command.ViewStatus)
	app.createView(app.currentView)

	// Calcule la hauteur disponible et propage aux vues.
	app.resize(width, height)

	return app
}

// defaultView resolves the configured landing view, falling back to the
// dashboard when the setting is missing or unparseable.
func defaultView(cfg *config.Config) command.ViewType {
	if cfg.App.DefaultView == "" {
		return command.ViewDashboard
	}
	parsed, err := command.Parse(cfg.App.DefaultView)
	if err != nil || parsed == "" {
		return command.ViewDashboard
	}
	return parsed
}

// Init initialise l'application
func (a *App) Init() tea.Cmd {
	// Note: resize() est déjà appelé dans newWithSize() pour initialiser les dimensions
	cmds := []tea.Cmd{a.tryAutoLogin()}

	if view, ok := a.views[a.currentView]; ok {
		cmds = append(cmds, view.Init())
	}

	return tea.Batch(cmds...)
}

// requestResize asks for a fresh layout at the current size. Every handler that
// changes what the window holds returns one, because the viewport height is
// budgeted against the header and the active view's footer.
func (a *App) requestResize() tea.Cmd {
	return func() tea.Msg {
		return tea.WindowSizeMsg{Width: a.width, Height: a.height}
	}
}

func (a *App) resize(width, height int) {
	a.width = width
	a.height = height

	// Rule 124: footer height is deducted from the viewport (tabs + optional info line)
	footerHeight := a.getFooterHeight()
	a.lastFooterHeight = footerHeight

	headerHeight := lipgloss.Height(a.renderHeader())
	availableHeight := height - headerHeight - footerHeight
	a.viewport.Width = width
	a.viewport.Height = availableHeight - 1 // -1 for the custom title border line

// resetSelectionModeFor takes a view out of selection mode before switching to
// it. Workspaces is dropped and rebuilt; the OCI view is reset in place because
// it holds scan results worth keeping.
func (a *App) resetSelectionModeFor(view command.ViewType) {
	switch view {
	case command.ViewWorkspaces:
		delete(a.views, view)
	case command.ViewOCIResources:
		if existing, ok := a.views[command.ViewOCIResources]; ok {
			updatedView, _ := existing.Update(ociresources.ResetSelectionMsg{})
			a.views[command.ViewOCIResources] = updatedView
		}
	}
}

// switchView change la vue courante
func (a *App) switchView(view command.ViewType) tea.Cmd {
	// Lazy loading des vues
	if _, exists := a.views[view]; !exists {
		a.createView(view)
	}

	a.currentView = view

	newView, ok := a.views[view]
	if !ok {
		return nil
	}
	log.Printf("Switching to view: %s, calling Init()", view)

	// Init() + un WindowSizeMsg pour forcer le redimensionnement
	return tea.Batch(newView.Init(), a.requestResize())
}

// createView crée une vue (lazy loading)
func (a *App) createView(view command.ViewType) {
	if _, exists := a.views[view]; exists && view != command.ViewGitlabAuth {
		return
	}

	switch view {
	case command.ViewDashboard:
		a.views[view] = dashboard.New(a.config, a.sharedState)
	case command.ViewStatus:
		a.views[view] = status.New(a.config)
	case command.ViewGitlabAuth:
		a.views[view] = a.newAuthView()
	case command.ViewGitlabExplorer:
		a.views[view] = explorer.New(a.config, a.sharedState)
	case command.ViewWorkspaces:
		a.views[view] = workspaces.New(a.config)
	case command.ViewSecurity:
		a.views[view] = security.New(a.config)
	case command.ViewContainers:
		a.views[view] = containers.New(a.config)
	case command.ViewOCIResources:
		a.views[view] = ociresources.New(a.config)
	case command.ViewNetdiag:
		a.views[view] = netdiag.New(a.config)
	}
}

// newAuthView builds the GitLab auth view against this context's credentials.
// It is rebuilt on every switch rather than cached, so the form reflects the
// session that is current now.
func (a *App) newAuthView() tea.Model {
	storage := credentials.NewChainStorage(
		credentials.NewFileStorageForContext(a.currentContext),
		credentials.NewGitCredentialStorageWithContext(a.currentContext),
	)
	log.Printf("Creating GitLab auth view with context: %s", a.currentContext)

	authView := auth.New(a.config, storage)
	if a.sharedState.GitLabClient != nil && a.sharedState.CurrentUser != nil {
		authView.SetAuth(a.sharedState.GitLabClient, a.sharedState.CurrentUser)
	}
	return authView
}

