package credentials

import (
	"fmt"
	"sync"
	"testing"
)

func TestMemoryStorage(t *testing.T) {
	storage := NewMemoryStorage()

	testURL := "https://gitlab.example.com"
	testToken := "test-token-12345"

	// Test Save
	err := storage.Save(testURL, testToken)
	if err != nil {
		t.Fatalf("Save() error: %v", err)
	}

	// Test Load
	token, err := storage.Load(testURL)
	if err != nil {
		t.Fatalf("Load() error: %v", err)
	}
	if token != testToken {
		t.Errorf("Expected token '%s', got '%s'", testToken, token)
	}

	// Test Load non-existent
	_, err = storage.Load("https://nonexistent.com")
	if err == nil {
		t.Error("Expected error when loading non-existent URL, got nil")
	}

	// Test Delete
	err = storage.Delete(testURL)
	if err != nil {
		t.Fatalf("Delete() error: %v", err)
	}

	// Verify deletion
	_, err = storage.Load(testURL)
	if err == nil {
		t.Error("Expected error after delete, got nil")
	}
}

func TestMemoryStorageMultipleURLs(t *testing.T) {
	storage := NewMemoryStorage()

	urls := map[string]string{
		"https://gitlab.com":         "token1",
		"https://gitlab.example.com": "token2",
		"https://custom.gitlab.org":  "token3",
	}

	// Save multiple
	for url, token := range urls {
		if err := storage.Save(url, token); err != nil {
			t.Fatalf("Save() error for %s: %v", url, err)
		}
	}

	// Load and verify
	for url, expectedToken := range urls {
		token, err := storage.Load(url)
		if err != nil {
			t.Fatalf("Load() error for %s: %v", url, err)
		}
		if token != expectedToken {
			t.Errorf("Expected token '%s' for %s, got '%s'", expectedToken, url, token)
		}
	}

	// Delete one
	if err := storage.Delete("https://gitlab.com"); err != nil {
		t.Fatalf("Delete() error: %v", err)
	}

	// Verify others still exist
	token, err := storage.Load("https://gitlab.example.com")
	if err != nil {
		t.Errorf("Load() error after deleting different URL: %v", err)
	}
	if token != "token2" {
		t.Errorf("Expected token 'token2', got '%s'", token)
	}
}

// MemoryStorage is the session fallback, which means one instance is shared by
// the Cmd goroutines of every view. Without the lock this is a data race, and
// `mise run test-race` is where it would surface.
func TestMemoryStorageSurvivesConcurrentUse(t *testing.T) {
	storage := NewMemoryStorage()

	const workers = 8
	var wg sync.WaitGroup
	wg.Add(workers)
	for i := range workers {
		go func() {
			defer wg.Done()
			url := fmt.Sprintf("https://gitlab-%d.example.com", i)
			for range 50 {
				_ = storage.Save(url, "tok")
				_, _ = storage.Load(url)
				_ = storage.Delete(url)
			}
		}()
	}
	wg.Wait()
}

package credentials

import (
	"errors"
	"strings"
	"testing"

	"github.com/zalando/go-keyring"
)

// mockKeyring swaps go-keyring's provider for an in-memory one. The provider is
// a package-level global in that library, so every test that touches the store
// has to install its own — and none of them may run in parallel.
func mockKeyring(t *testing.T) {
	t.Helper()
	keyring.MockInit()
}

func TestKeyringStorageRoundTrip(t *testing.T) {
	mockKeyring(t)
	storage := NewKeyringStorage("default")

	if err := storage.Save("https://gitlab.example.com", "glpat-secret"); err != nil {
		t.Fatalf("Save() error = %v", err)
	}

	got, err := storage.Load("https://gitlab.example.com")
	if err != nil {
		t.Fatalf("Load() error = %v", err)
	}
	if got != "glpat-secret" {
		t.Errorf("Load() = %q, want glpat-secret", got)
	}

	if err := storage.Delete("https://gitlab.example.com"); err != nil {
		t.Fatalf("Delete() error = %v", err)
	}
	if _, err := storage.Load("https://gitlab.example.com"); err == nil {
		t.Error("Load() after Delete returned no error")
	}
}

// Two contexts pointing at the same host are the case the whole context-scoping
// exists for: without it the last one to authenticate wins for both.
func TestKeyringStorageIsolatesContexts(t *testing.T) {
	mockKeyring(t)
	const url = "https://gitlab.example.com"

	work := NewKeyringStorage("work")
	personal := NewKeyringStorage("personal")

	if err := work.Save(url, "work-token"); err != nil {
		t.Fatalf("work Save() error = %v", err)
	}
	if err := personal.Save(url, "personal-token"); err != nil {
		t.Fatalf("personal Save() error = %v", err)
	}

	got, err := work.Load(url)
	if err != nil {
		t.Fatalf("work Load() error = %v", err)
	}
	if got != "work-token" {
		t.Errorf("work Load() = %q, want work-token — the personal context overwrote it", got)
	}
}

func TestNewKeyringStorageDefaultsTheContext(t *testing.T) {
	tests := []struct {
		name string
		in   string
		want string
	}{
		{"empty context falls back to default", "", "default"},
		{"named context is kept", "prod", "prod"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := NewKeyringStorage(tt.in).context; got != tt.want {
				t.Errorf("context = %q, want %q", got, tt.want)
			}
		})
	}
}

// Deleting a secret that is not there succeeds: logout must not fail because
// the token was already gone.
func TestKeyringStorageDeleteIsIdempotent(t *testing.T) {
	mockKeyring(t)

	if err := NewKeyringStorage("default").Delete("https://never-saved.example.com"); err != nil {
		t.Errorf("Delete() on a missing entry = %v, want nil", err)
	}
}

func TestKeyringStorageReportsBackendFailures(t *testing.T) {
	keyring.MockInitWithError(errors.New("no D-Bus session"))
	t.Cleanup(keyring.MockInit)
	storage := NewKeyringStorage("default")

	for _, tt := range []struct {
		name string
		op   func() error
	}{
		{"Save", func() error { return storage.Save("https://gitlab.example.com", "tok") }},
		{"Load", func() error { _, err := storage.Load("https://gitlab.example.com"); return err }},
		{"Delete", func() error { return storage.Delete("https://gitlab.example.com") }},
	} {
		t.Run(tt.name, func(t *testing.T) {
			err := tt.op()
			if err == nil {
				t.Fatalf("%s() with an unreachable store returned no error", tt.name)
			}
			// The message has to name the store: "keyring error" tells a user
			// nothing about where to go looking.
			if !strings.Contains(err.Error(), KeyringName()) {
				t.Errorf("%s() error = %q, want it to name %q", tt.name, err, KeyringName())
			}
		})
	}
}

func TestKeyringAvailable(t *testing.T) {
	tests := []struct {
		name  string
		setup func()
		want  bool
	}{
		{"a store that answers", keyring.MockInit, true},
		{
			"a store that is not there",
			func() { keyring.MockInitWithError(errors.New("no D-Bus session")) },
			false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tt.setup()
			t.Cleanup(keyring.MockInit)

			if got := KeyringAvailable(); got != tt.want {
				t.Errorf("KeyringAvailable() = %v, want %v", got, tt.want)
			}
		})
	}
}

// The probe must never leave an entry behind: it runs on every launch, on
// machines where the store may turn out to be unusable.
func TestKeyringAvailableWritesNothing(t *testing.T) {
	mockKeyring(t)

	KeyringAvailable()

	if _, err := keyring.Get(keyringService, keyringProbeAccount); !errors.Is(err, keyring.ErrNotFound) {
		t.Errorf("probe account exists after KeyringAvailable(): err = %v, want ErrNotFound", err)
	}
}

func TestKeyringNameIsNotEmpty(t *testing.T) {
	if KeyringName() == "" {
		t.Error("KeyringName() is empty — it is shown to the user on every platform")
	}
}

package credentials

import (
	"errors"
	"strings"
	"testing"

	"github.com/zalando/go-keyring"
)

func TestUsableHelperName(t *testing.T) {
	tests := []struct {
		name     string
		value    string
		wantName string
		wantOK   bool
	}{
		{"a real helper", "manager", "manager", true},
		{"platform helper", "osxkeychain", "osxkeychain", true},
		{"a helper with arguments", "libsecret --timeout 5", "libsecret", true},
		{"a shell command helper", "!/usr/local/bin/my-helper", "/usr/local/bin/my-helper", true},
		{"surrounding whitespace", "  wincred  ", "wincred", true},

		// `store` keeps credentials in ~/.git-credentials in plaintext. Moving
		// the token from one plaintext file to another is not a fix.
		{"store is refused", "store", "", false},
		{"store with a file argument is refused", "store --file=/tmp/creds", "", false},

		// An unset helper means git has nowhere to put the secret, and would
		// quietly succeed at storing nothing.
		{"empty is refused", "", "", false},
		{"whitespace only is refused", "   ", "", false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			gotName, gotOK := usableHelperName(tt.value)
			if gotOK != tt.wantOK {
				t.Fatalf("usableHelperName(%q) ok = %v, want %v", tt.value, gotOK, tt.wantOK)
			}
			if gotName != tt.wantName {
				t.Errorf("usableHelperName(%q) name = %q, want %q", tt.value, gotName, tt.wantName)
			}
		})
	}
}

func TestGitHelperUsable(t *testing.T) {
	tests := []struct {
		name     string
		helper   string
		wantName string
		wantOK   bool
	}{
		{"a helper that reaches a real store", "manager", "manager", true},
		{"the plaintext store helper", "store", "", false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			hermeticGitWithHelper(t, tt.helper)

			gotName, gotOK := gitHelperUsable()
			if gotOK != tt.wantOK {
				t.Fatalf("gitHelperUsable() ok = %v, want %v", gotOK, tt.wantOK)
			}
			if gotName != tt.wantName {
				t.Errorf("gitHelperUsable() = %q, want %q", gotName, tt.wantName)
			}
		})
	}
}

// git resolves the last helper that answers, so the last usable one in the list
// is the one whose name should be reported.
func TestGitHelperUsablePrefersTheLastConfiguredHelper(t *testing.T) {
	hermeticGitWithHelper(t, "store\n\thelper = manager")

	got, ok := gitHelperUsable()
	if !ok {
		t.Fatal("gitHelperUsable() = false, want the trailing manager entry to win")
	}
	if got != "manager" {
		t.Errorf("gitHelperUsable() = %q, want manager", got)
	}
}

func TestSelectPrefersTheHostStore(t *testing.T) {
	mockKeyring(t)

	sel := Select("work", PreferenceAuto)

	if sel.Backend != BackendKeyring {
		t.Fatalf("Backend = %q, want %q", sel.Backend, BackendKeyring)
	}
	if !sel.Persists() {
		t.Error("Persists() = false for the host store")
	}
	if !strings.Contains(sel.Detail, KeyringName()) {
		t.Errorf("Detail = %q, want it to name %q", sel.Detail, KeyringName())
	}
	// The storage has to be scoped to the context it was asked for.
	if ks, ok := sel.Storage.(*KeyringStorage); !ok || ks.context != "work" {
		t.Errorf("Storage = %T scoped to %v, want a *KeyringStorage on work", sel.Storage, sel.Storage)
	}
}

func TestSelectFallsBackToGitWhenNoHostStoreAnswers(t *testing.T) {
	unreachableKeyring(t)
	hermeticGitWithHelper(t, "manager")

	sel := Select("work", PreferenceAuto)

	if sel.Backend != BackendGitCredential {
		t.Fatalf("Backend = %q, want %q", sel.Backend, BackendGitCredential)
	}
	if !strings.Contains(sel.Detail, "manager") {
		t.Errorf("Detail = %q, want it to name the helper", sel.Detail)
	}
}

// The last resort is deliberately the worst option: nothing is written, and the
// user has to be able to tell without reading the source.
func TestSelectFallsBackToMemoryWhenNothingCanStoreASecret(t *testing.T) {
	unreachableKeyring(t)
	hermeticGitWithHelper(t, "store")

	sel := Select("work", PreferenceAuto)

	if sel.Backend != BackendMemory {
		t.Fatalf("Backend = %q, want %q", sel.Backend, BackendMemory)
	}
	if sel.Persists() {
		t.Error("Persists() = true for the memory fallback")
	}
	if !strings.Contains(sel.Detail, "Nothing is saved") {
		t.Errorf("Detail = %q, want it to say plainly that nothing is saved", sel.Detail)
	}
}

func TestSelectHonoursThePreference(t *testing.T) {
	tests := []struct {
		name       string
		preference string
		want       Backend
	}{
		{"pinned to the host store", PreferenceKeyring, BackendKeyring},
		{"pinned to git", PreferenceGitCredential, BackendGitCredential},
		{"unset means auto", "", BackendKeyring},
		{"an unknown value means auto", "nonsense", BackendKeyring},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			mockKeyring(t)
			hermeticGitWithHelper(t, "manager")

			if got := Select("work", tt.preference).Backend; got != tt.want {
				t.Errorf("Backend = %q, want %q", got, tt.want)
			}
		})
	}
}

// A pinned backend that turns out to be unreachable falls through to memory,
// not to the other backend: someone who asked for the host store should not be
// handed a git helper without being told.
func TestSelectDoesNotSubstituteAPinnedBackend(t *testing.T) {
	tests := []struct {
		name       string
		preference string
		setup      func(t *testing.T)
	}{
		{
			"host store pinned but unreachable, with git available",
			PreferenceKeyring,
			func(t *testing.T) {
				unreachableKeyring(t)
				hermeticGitWithHelper(t, "manager")
			},
		},
		{
			"git pinned but unusable, with the host store available",
			PreferenceGitCredential,
			func(t *testing.T) {
				mockKeyring(t)
				hermeticGitWithHelper(t, "store")
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			tt.setup(t)

			if got := Select("work", tt.preference).Backend; got != BackendMemory {
				t.Errorf("Backend = %q, want %q", got, BackendMemory)
			}
		})
	}
}

func TestSessionOnlyAlwaysHasAStorage(t *testing.T) {
	sel := SessionOnly("under test")

	if sel.Storage == nil {
		t.Fatal("Storage is nil — views would have to guard against it")
	}
	if err := sel.Storage.Save("https://gitlab.example.com", "tok"); err != nil {
		t.Errorf("Save() error = %v", err)
	}
}

// unreachableKeyring makes the host store answer with a backend error, which is
// what a headless Linux box with no D-Bus session looks like.
func unreachableKeyring(t *testing.T) {
	t.Helper()
	keyring.MockInitWithError(errors.New("no D-Bus session"))
	t.Cleanup(keyring.MockInit)
}

