package config

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeContextFile drops a raw YAML context file into the temp home, bypassing
// SaveContext — which is the point: these tests are about what an *older*
// DevDesk wrote, and the current schema can no longer express it.
func writeContextFile(t *testing.T, contextName, body string) string {
	t.Helper()
	home := setupTmpHome(t)
	dir := filepath.Join(home, ".devdesk")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("creating config dir: %v", err)
	}
	path, err := GetContextPath(contextName)
	if err != nil {
		t.Fatalf("GetContextPath: %v", err)
	}
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing context file: %v", err)
	}
	return path
}

const legacyContext = `app:
    theme: mocha
gitlab:
    url: https://gitlab.example.com
    token: glpat-plaintext
    clone_method: https
registry:
    url: https://registry.example.com
    username: builder
    password: hunter2
`

func TestReadLegacySecrets(t *testing.T) {
	writeContextFile(t, "default", legacyContext)

	got, err := ReadLegacySecrets("default")
	if err != nil {
		t.Fatalf("ReadLegacySecrets() error = %v", err)
	}

	want := LegacySecrets{
		GitLabURL:        "https://gitlab.example.com",
		GitLabToken:      "glpat-plaintext",
		RegistryURL:      "https://registry.example.com",
		RegistryPassword: "hunter2",
	}
	if got != want {
		t.Errorf("ReadLegacySecrets() = %+v, want %+v", got, want)
	}
	if got.Empty() {
		t.Error("Empty() = true for a file holding two secrets")
	}
}

func TestReadLegacySecretsOnACleanFile(t *testing.T) {
	writeContextFile(t, "default", "gitlab:\n    url: https://gitlab.example.com\n")

	got, err := ReadLegacySecrets("default")
	if err != nil {
		t.Fatalf("ReadLegacySecrets() error = %v", err)
	}
	if !got.Empty() {
		t.Errorf("Empty() = false for %+v, want true — nothing to migrate", got)
	}
}

// A context that does not exist yet is the normal case on first launch, not an
// error condition.
func TestReadLegacySecretsOnAMissingFile(t *testing.T) {
	setupTmpHome(t)

	got, err := ReadLegacySecrets("default")
	if err != nil {
		t.Fatalf("ReadLegacySecrets() error = %v, want nil for a missing file", err)
	}
	if !got.Empty() {
		t.Errorf("ReadLegacySecrets() = %+v, want empty", got)
	}
}

func TestRemoveLegacySecrets(t *testing.T) {
	path := writeContextFile(t, "default", legacyContext)

	if err := RemoveLegacySecrets("default", true, true); err != nil {
		t.Fatalf("RemoveLegacySecrets() error = %v", err)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading rewritten file: %v", err)
	}
	body := string(data)

	for _, secret := range []string{"glpat-plaintext", "hunter2", "token:", "password:"} {
		if strings.Contains(body, secret) {
			t.Errorf("rewritten file still contains %q:\n%s", secret, body)
		}
	}

	// Everything else has to survive: this is somebody's configuration file,
	// not a scratch buffer.
	for _, kept := range []string{"theme: mocha", "url: https://gitlab.example.com", "clone_method: https", "username: builder"} {
		if !strings.Contains(body, kept) {
			t.Errorf("rewritten file lost %q:\n%s", kept, body)
		}
	}
}

// The caller passes true only for a secret it has already stored elsewhere. A
// store that refused the write must leave the file alone rather than losing it.
func TestRemoveLegacySecretsOnlyRemovesWhatItIsAskedTo(t *testing.T) {
	path := writeContextFile(t, "default", legacyContext)

	if err := RemoveLegacySecrets("default", true, false); err != nil {
		t.Fatalf("RemoveLegacySecrets() error = %v", err)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading rewritten file: %v", err)
	}
	body := string(data)

	if strings.Contains(body, "glpat-plaintext") {
		t.Errorf("the token was not removed:\n%s", body)
	}
	if !strings.Contains(body, "hunter2") {
		t.Errorf("the registry password was removed without being asked for:\n%s", body)
	}
}

func TestRemoveLegacySecretsOnACleanFileChangesNothing(t *testing.T) {
	const clean = "gitlab:\n    url: https://gitlab.example.com\n"
	path := writeContextFile(t, "default", clean)

	if err := RemoveLegacySecrets("default", true, true); err != nil {
		t.Fatalf("RemoveLegacySecrets() error = %v", err)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading file: %v", err)
	}
	if string(data) != clean {
		t.Errorf("file was rewritten with nothing to remove:\ngot  %q\nwant %q", data, clean)
	}
}

// The rewritten file still has to load.
func TestRemoveLegacySecretsLeavesALoadableFile(t *testing.T) {
	writeContextFile(t, "default", legacyContext)

	if err := RemoveLegacySecrets("default", true, true); err != nil {
		t.Fatalf("RemoveLegacySecrets() error = %v", err)
	}

	cfg, err := LoadContext("default")
	if err != nil {
		t.Fatalf("LoadContext() after the rewrite: %v", err)
	}
	if cfg.GitLab.URL != "https://gitlab.example.com" {
		t.Errorf("GitLab.URL = %q, want it preserved", cfg.GitLab.URL)
	}
	if cfg.App.Theme != "mocha" {
		t.Errorf("App.Theme = %q, want mocha", cfg.App.Theme)
	}
}

func TestRemoveLegacySecretsOnAMissingFile(t *testing.T) {
	setupTmpHome(t)

	if err := RemoveLegacySecrets("default", true, true); err != nil {
		t.Errorf("RemoveLegacySecrets() on a missing file = %v, want nil", err)
	}
}

func TestLegacySecretsReadRejectsAnInvalidContextName(t *testing.T) {
	setupTmpHome(t)

	if _, err := ReadLegacySecrets("Not A Context"); err == nil {
		t.Error("ReadLegacySecrets() with an invalid context name returned no error")
	}
	if err := RemoveLegacySecrets("Not A Context", true, true); err == nil {
		t.Error("RemoveLegacySecrets() with an invalid context name returned no error")
	}
}

package credentials

import (
	"errors"
	"os"
	"path/filepath"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/config"
)

// legacyContextFile writes a raw context file into a temp home. It bypasses
// config.SaveContext deliberately: the current schema can no longer express the
// plaintext fields this whole migration exists to remove.
func legacyContextFile(t *testing.T, body string) string {
	t.Helper()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("USERPROFILE", home)

	dir := filepath.Join(home, ".devdesk")
	if err := os.MkdirAll(dir, 0o755); err != nil {
		t.Fatalf("creating config dir: %v", err)
	}
	path := filepath.Join(dir, "config.yaml")
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("writing context file: %v", err)
	}
	return path
}

const legacyBoth = `gitlab:
    url: https://gitlab.example.com
    token: glpat-plaintext
registry:
    url: https://registry.example.com
    password: hunter2
`

func TestMigrateLegacySecretsMovesBothSecrets(t *testing.T) {
	path := legacyContextFile(t, legacyBoth)
	store := NewMemoryStorage()

	notes := MigrateLegacySecrets(store, "default")

	if len(notes) != 2 {
		t.Errorf("notes = %v, want one per secret moved", notes)
	}

	token, err := store.Load("https://gitlab.example.com")
	if err != nil || token != "glpat-plaintext" {
		t.Errorf("token in store = %q (err %v), want glpat-plaintext", token, err)
	}
	password, err := store.Load("https://registry.example.com")
	if err != nil || password != "hunter2" {
		t.Errorf("password in store = %q (err %v), want hunter2", password, err)
	}

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading rewritten file: %v", err)
	}
	if body := string(data); strings.Contains(body, "glpat-plaintext") || strings.Contains(body, "hunter2") {
		t.Errorf("the plaintext survived in the config file:\n%s", body)
	}
}

// The normal case, on every launch after the first: nothing to say and nothing
// written.
func TestMigrateLegacySecretsIsSilentWhenThereIsNothingToMove(t *testing.T) {
	legacyContextFile(t, "gitlab:\n    url: https://gitlab.example.com\n")

	if notes := MigrateLegacySecrets(NewMemoryStorage(), "default"); notes != nil {
		t.Errorf("notes = %v, want none", notes)
	}
}

// A store that refuses the write must leave the plaintext where it is: losing
// the secret would be worse than leaving it, and the user has to be told.
func TestMigrateLegacySecretsKeepsThePlaintextWhenTheStoreRefuses(t *testing.T) {
	path := legacyContextFile(t, legacyBoth)

	notes := MigrateLegacySecrets(failingStorage{}, "default")

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading file: %v", err)
	}
	if !strings.Contains(string(data), "glpat-plaintext") {
		t.Error("the token was deleted from the config file without being stored anywhere")
	}
	if len(notes) == 0 || !strings.Contains(strings.Join(notes, " "), "still in plaintext") {
		t.Errorf("notes = %v, want the failure said plainly", notes)
	}
}

// A secret with no URL has no key to be filed under and no host DevDesk could
// use it against. It is unusable plaintext, so it goes — and the user is told.
func TestMigrateLegacySecretsDropsASecretWithNoURL(t *testing.T) {
	path := legacyContextFile(t, "gitlab:\n    token: glpat-orphan\n")
	store := NewMemoryStorage()

	notes := MigrateLegacySecrets(store, "default")

	data, err := os.ReadFile(path)
	if err != nil {
		t.Fatalf("reading file: %v", err)
	}
	if strings.Contains(string(data), "glpat-orphan") {
		t.Errorf("the unusable token survived:\n%s", data)
	}
	if len(notes) != 1 || !strings.Contains(notes[0], "no URL") {
		t.Errorf("notes = %v, want the reason spelled out", notes)
	}
}

func TestMigrateLegacySecretsOnAMissingContext(t *testing.T) {
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("USERPROFILE", home)

	if notes := MigrateLegacySecrets(NewMemoryStorage(), "default"); notes != nil {
		t.Errorf("notes = %v, want none for a context that does not exist", notes)
	}
}

func TestMigrateLegacySecretsOnAnInvalidContextName(t *testing.T) {
	if notes := MigrateLegacySecrets(NewMemoryStorage(), "Not A Context"); notes != nil {
		t.Errorf("notes = %v, want none", notes)
	}
}

// Guard against the migration reading fields the schema still carries: if
// GitLabConfig ever grows a Token back, this fails.
func TestConfigSchemaHoldsNoSecrets(t *testing.T) {
	var cfg config.Config
	_ = cfg
	// Compilation is the assertion. cfg.GitLab.Token and cfg.Registry.Password
	// no longer exist, and adding either back breaks this file.
}

type failingStorage struct{}

