func TestKeysAreIgnoredWhileAuthenticating(t *testing.T) {
	m := newTestModel(t, testConfig(), newFakeStorage())
	m.urlInput.SetValue("https://gitlab.example.com")
	m.tokenInput.SetValue("glpat-x")
